import { Component } from '@angular/core';
import { ActivatedRoute } from "@angular/router";
@Component({
  selector: 'app-data-sharing-type-four',
  templateUrl: './data-sharing-type-four.component.html',
  styleUrls: ['./data-sharing-type-four.component.scss']
})
export class DataSharingTypeFourComponent {
  code1 = `{
    path:"abc/:salary",
    component:your component name,
    data : { name:ramu , salary :1200}
}`;

code2 = `<a routerLink="abc/1200">click me </a>`;

code3 = `this.activatedRouteObj.data.subscribe(
  (dataOne : any) => {
    console.log(dataOne);
  }
);`;

code4 = `{ name:ramu , salary :1200}`;

constructor(activatedRouteObj : ActivatedRoute){
    activatedRouteObj.data.subscribe(
      (dataOne : any) => {
        console.log(dataOne);
      }
    );
}
}
<h3>using data property in routing</h3>
            <pre> If route is abc and data is  {{code4}}  then routing will be like below </pre>
            <pre> {{code1}}</pre>

            <p>Now to get the data into the ts-file follow the below process  </p>
                <ol>
                    <li>import ActivatedRoute</li>
                    <li>create  ActivatedRoute object in the constructor   </li>
                    <li>Now subscribe to data property in the ActivatedRoute class </li>
                    <li>Now it will show the value of the data </li>
                </ol>

                <pre>{{code3}}</pre>
